const w = vars.width, h = vars.height, n = Math.max(2, Math.round(vars.segments)), st = vars.style;
const P = [[-w / 2, -0.05, 0]];
if (st === 'pointed') {
  const sh = Math.max(0, h - w * Math.sqrt(3) / 2);
  P.push([-w / 2, sh, 0]);
  for (let i = 1; i < n; i++) { const a = PI - (PI / 3) * i / n; P.push([w / 2 + w * Math.cos(a), sh + w * Math.sin(a), 0]); }
  P.push([0, sh + w * Math.sqrt(3) / 2, 0]);
  for (let i = n - 1; i >= 1; i--) { const a = (PI / 3) * i / n; P.push([-w / 2 + w * Math.cos(a), sh + w * Math.sin(a), 0]); }
  P.push([w / 2, sh, 0]);
} else if (st === 'flat') {
  P.push([-w / 2, h, 0], [w / 2, h, 0]);
} else {
  const sh = Math.max(0, h - w / 2);
  for (let i = 0; i <= n; i++) { const a = PI - PI * i / n; P.push([Math.cos(a) * w / 2, sh + Math.sin(a) * w / 2, 0]); }
}
P.push([w / 2, -0.05, 0]);
addprim(0, 'poly', P.map((p) => addpoint(0, p)));

const w = vars.width, h = vars.height, t = vars.thickness, D = vars.depth;
const sh = vars.style === 'pointed' ? Math.max(0, h - w * Math.sqrt(3) / 2) : vars.style === 'flat' ? h : Math.max(0, h - w / 2);
const add = (p, s) => { const q = addpoint(0, p); setpointattrib(0, 'scale', q, s); };
add([0, h + t * 0.55, 0], [Math.min(t * 0.8, w * 0.3), t * 1.1, D + 0.04]);
if (vars.style !== 'flat') for (const sx of [-1, 1]) add([sx * (w / 2 + t / 2), sh - 0.06, 0], [t + 0.08, 0.12, D + 0.04]);
